// Generates the browser build of the xCCalc engine from the Node sources, so there is one source of truth.
//   node scripts/sync-xccalc-core.cjs           write web/js/xccalc/core/xcc-core.js and xcc-data.js
//   node scripts/sync-xccalc-core.cjs --check   exit 1 when the generated files are out of date
// xcc-core.js = a tiny CommonJS shim + tools/calccore.cjs, xccalc/xcsformat.cjs, xccalc/xcsio.cjs and what they require.
// Result: window.XCC = { C: calccore, F: xcsformat, IO: xcsio }. Plain script tags, no build step, works from file://.
// xcc-data.js = the ACWriter 4x7 font (tools/acwriter/font4.json, read only) for the Atari view.
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..'), out = path.join(root, 'web', 'js', 'xccalc', 'core');
const MODULES = ['inflate.cjs', 'craftcore/util.cjs', 'craftcore/encodings.cjs', 'calccore.cjs', 'xccalc/xcsformat.cjs', 'xccalc/xcsio.cjs'];

const SHIM = `const __mods = {}, __defs = {};
function __def(name, fn) { __defs[name] = fn; }
function __require(name) {
  const n = name.replace(/^.*\\//, '');
  if (n === 'zlib') throw new Error('zlib is not available in the browser');
  if (!__mods[n]) {
    if (!__defs[n]) throw new Error('module not bundled: ' + name);
    const m = { exports: {} }; __mods[n] = m; __defs[n](m, m.exports, __require);
  }
  return __mods[n].exports;
}
`;

function core() {
  let s = '// GENERATED by scripts/sync-xccalc-core.cjs from tools/*.cjs - do not edit.\n(function (global) {\n\'use strict\';\n' + SHIM;
  for (const m of MODULES) {
    s += '__def(' + JSON.stringify(path.basename(m)) + ', function (module, exports, require) {\n' + fs.readFileSync(path.join(root, 'tools', m), 'utf8').replace(/\r\n/g, '\n').replace(/^#!.*\n/, '') + '\n});\n';
  }
  return s + 'global.XCC = { C: __require("calccore.cjs"), F: __require("xcsformat.cjs"), IO: __require("xcsio.cjs") };\n})(typeof window !== "undefined" ? window : globalThis);\n';
}

function data() {
  const font4 = JSON.parse(fs.readFileSync(path.join(root, 'tools', 'acwriter', 'font4.json'), 'utf8'));
  return '// GENERATED by scripts/sync-xccalc-core.cjs - ACWriter 4x7 font (ASCII 32..127, 7 rows of 4 bits) used by the xCCalc Atari view.\n' +
    'window.XCC_DATA = ' + JSON.stringify({ font4 }) + ';\n';
}

const files = { 'xcc-core.js': core(), 'xcc-data.js': data() };
if (process.argv.includes('--check')) {
  const bad = Object.keys(files).filter((f) => !fs.existsSync(path.join(out, f)) || fs.readFileSync(path.join(out, f), 'utf8') !== files[f]);
  if (bad.length) { console.error('out of date: ' + bad.join(', ') + ' (run node scripts/sync-xccalc-core.cjs)'); process.exit(1); }
  console.log('xccalc core up to date');
} else {
  fs.mkdirSync(out, { recursive: true });
  for (const f of Object.keys(files)) fs.writeFileSync(path.join(out, f), files[f]);
  console.log('wrote ' + Object.keys(files).map((f) => f + ' (' + files[f].length + ')').join(', '));
}
